import assert from "node:assert/strict";
import { it } from "node:test";
import { Volume } from "memfs";
import { encodeWav } from "@poe-code/audio-ast";
import { parseWav } from "@poe-code/mp4-ast";
import { createFfmpegCommand, evalSyncFfmpeg } from "./index.js";

const samples = [-32768, -16385, -257, -1, 0, 1, 257, 16385, 32767];
// Generated by native FFmpeg from independently packed PCM16 WAV samples.
const aiff = Buffer.from("464f524d0000004041494646434f4d4d000000120001000000090010400bfa0000000000000053534e440000001a00000000000000008000bffffeffffff00000001010140017fff", "hex");
const wav = encodeWav({ sampleRate: 8000, channels: [Float64Array.from(samples, value => value / 32768)] });

for (const sync of [false, true]) {
  for (const decoding of [false, true]) {
    for (const forced of [false, true]) {
      it(`${sync ? "sync" : "async"} ${forced ? "forced" : "inferred"} AIFF ${decoding ? "decode" : "encode"}`, async () => {
        const volume = Volume.fromJSON({});
        const input = decoding ? "/in.aiff" : "/in.wav";
        const output = forced ? "/out.bin" : decoding ? "/out.wav" : "/out.aif";
        volume.writeFileSync(input, decoding ? aiff : wav);
        const args = ["-y", "-v", "error", ...(forced && decoding ? ["-f", "aiff"] : []), "-i", input, ...(decoding ? ["-c:a", "pcm_s16le"] : []),
          ...(forced ? ["-f", decoding ? "wav" : "aiff"] : []), output];
        if (sync) {
          assert.equal(evalSyncFfmpeg(args, undefined,
            name => volume.existsSync(name) ? volume.readFileSync(name) as Buffer : undefined,
            (name, bytes) => { volume.writeFileSync(name, bytes); return true; }), "");
        } else {
          let stderr = "";
          const result = await createFfmpegCommand().execute({
            args, cwd: "/", env: {}, signal: new AbortController().signal,
            fs: {
              async readFile(name: string) { return volume.readFileSync(name); },
              async writeFile(name: string, bytes: Uint8Array) { volume.writeFileSync(name, bytes); },
              async stat(name: string) { return volume.statSync(name); }
            },
            stdin: (async function* () {})(), stdout: { async write() {} },
            stderr: { async write(bytes: Uint8Array) { stderr += new TextDecoder().decode(bytes); } }
          } as never);
          assert.equal(result.exitCode, 0, stderr);
        }
        const bytes = volume.readFileSync(output) as Buffer;
        if (!decoding) assert.deepEqual(bytes, aiff);
        else {
          assert.equal(bytes.readUInt16LE(20), 1);
          assert.equal(bytes.readUInt16LE(34), 16);
          const audio = parseWav(bytes).tracks[0]!.decodedAudio!;
          assert.deepEqual(Array.from(audio.channelData[0]!, sample => sample * 32768), samples);
        }
      });
    }
  }
}

it("reads native AIFF-C sowt input as exact little-endian PCM", async () => {
  const volume = Volume.fromJSON({});
  volume.writeFileSync("/in.aiff", Buffer.from("464f524d00000058414946434656455200000004a28051404e414d45000000064e6565646c65434f4d4d000000180001000000050010400bfa00000000000000736f7774000053534e440000001200000000000000000080fffe00000101ff7f", "hex"));
  let stderr = "";
  const result = await createFfmpegCommand().execute({
    args: ["-y", "-v", "error", "-i", "/in.aiff", "-f", "s16le", "/out.raw"],
    cwd: "/", env: {}, signal: new AbortController().signal,
    fs: {
      async readFile(name: string) { return volume.readFileSync(name); },
      async writeFile(name: string, bytes: Uint8Array) { volume.writeFileSync(name, bytes); },
      async stat(name: string) { return volume.statSync(name); }
    },
    stdin: (async function* () {})(), stdout: { async write() {} },
    stderr: { async write(bytes: Uint8Array) { stderr += new TextDecoder().decode(bytes); } }
  } as never);
  assert.equal(result.exitCode, 0, stderr);
  assert.equal((volume.readFileSync("/out.raw") as Buffer).toString("hex"), "0080fffe00000101ff7f");
});

for (const sync of [false, true]) {
  it(`${sync ? "sync" : "async"} writes little-endian PCM as AIFF-C sowt`, async () => {
    const volume = Volume.fromJSON({});
    volume.writeFileSync("/in.wav", wav);
    const args = ["-y", "-v", "error", "-i", "/in.wav", "-metadata", "title=Needle",
      "-metadata", "artist=Tester", "-c:a", "pcm_s16le", "/out.aiff"];
    if (sync) {
      assert.equal(evalSyncFfmpeg(args, undefined,
        name => volume.existsSync(name) ? volume.readFileSync(name) as Buffer : undefined,
        (name, bytes) => { volume.writeFileSync(name, bytes); return true; }), "");
    } else {
      let stderr = "";
      const result = await createFfmpegCommand().execute({
        args, cwd: "/", env: {}, signal: new AbortController().signal,
        fs: {
          async readFile(name: string) { return volume.readFileSync(name); },
          async writeFile(name: string, bytes: Uint8Array) { volume.writeFileSync(name, bytes); },
          async stat(name: string) { return volume.statSync(name); }
        },
        stdin: (async function* () {})(), stdout: { async write() {} },
        stderr: { async write(bytes: Uint8Array) { stderr += new TextDecoder().decode(bytes); } }
      } as never);
      assert.equal(result.exitCode, 0, stderr);
    }
    const bytes = volume.readFileSync("/out.aiff") as Buffer;
    assert.equal(bytes.toString("ascii", 8, 12), "AIFC");
    assert.equal(bytes.toString("ascii", 64, 68), "sowt");
    const sound = bytes.indexOf(Buffer.from("SSND")) + 16;
    assert.deepEqual(bytes.subarray(sound, sound + samples.length * 2), Buffer.from(aiff.subarray(54)).swap16());
  });
}

for (const frames of [0, 2, 4, 6]) {
  it(`decodes all available AIFF samples when COMM declares ${frames} frames`, async () => {
    const volume = Volume.fromJSON({});
    const input = Buffer.from("464f524d0000003641494646434f4d4d000000120001000000040010400bfa0000000000000053534e440000001000000000000000000064ff38012cfe70", "hex");
    input.writeUInt32BE(frames, 22);
    volume.writeFileSync("/in.aiff", input);
    let stderr = "";
    const result = await createFfmpegCommand().execute({
      args: ["-y", "-v", "error", "-i", "/in.aiff", "-f", "s16le", "/out.raw"],
      cwd: "/", env: {}, signal: new AbortController().signal,
      fs: {
        async readFile(name: string) { return volume.readFileSync(name); },
        async writeFile(name: string, bytes: Uint8Array) { volume.writeFileSync(name, bytes); },
        async stat(name: string) { return volume.statSync(name); }
      },
      stdin: (async function* () {})(), stdout: { async write() {} },
      stderr: { async write(bytes: Uint8Array) { stderr += new TextDecoder().decode(bytes); } }
    } as never);
    assert.equal(result.exitCode, 0, stderr);
    assert.equal((volume.readFileSync("/out.raw") as Buffer).toString("hex"), "640038ff2c0170fe");
    assert.equal(evalSyncFfmpeg(["-y", "-i", "/in.aiff", "-f", "s16le", "/sync.raw"], undefined,
      name => volume.existsSync(name) ? volume.readFileSync(name) as Buffer : undefined,
      (name, bytes) => { volume.writeFileSync(name, bytes); return true; }), "");
    assert.deepEqual(volume.readFileSync("/sync.raw"), volume.readFileSync("/out.raw"));
  });
}
